    s += bunsenSVG(80, 288);
    // Thermometer in the neck
    s += `<line x1="80" y1="124" x2="80" y2="176" stroke="#000000" stroke-width="1.2"/>`;
    s += `<circle cx="80" cy="178" r="3" fill="#000000"/>`;
    // Liebig condenser, sloping down to the right
